8	// 本文件为 Status 查询结果的相互独立性补充回归保障。Status 返回的
9	// MonthlyUsage、Bills 与 ScheduledEnd 都必须是调用方私有的快照副本：
10	//   - 调用方整理（重排、替换）或篡改自己拿到的结果只能留在该份结果中，
11	//     不能回写账户，后续查询、MonthlyUsage 与 GetBill 仍显示真实数据；
12	//   - 同一账户先后取得的两份状态彼此独立，互不改写；
13	//   - 账户后续正常操作（补报未出账月份用量、登记部分付款、撤回取消）
14	//     只反映在新查询中，旧结果定格在取得它的时刻；
15	//   - 篡改旧结果中的终止时刻既不能提前/推迟真实终止，也不能在撤回取消
16	//     后凭空重新登记取消；没有取消安排时编辑结果也不能制造安排。
17	
18	// mustRecordEvent 登记一条用量事件，失败即终止测试。
19	func mustRecordEvent(t *testing.T, s *Service, e Event) {
20		t.Helper()
21		if r, err := s.RecordEvent(e); err != nil {
22			t.Fatalf("record event %q: %v", e.EventID, err)
23		} else if !r.Accepted {
24			t.Fatalf("record event %q unexpectedly deduplicated", e.EventID)
25		}
26	}
27	
28	// statusUsageTotal 在状态结果中查找指定账期的累计用量，缺失即终止。
29	func statusUsageTotal(t *testing.T, st AccountStatus, p Month) int64 {
30		t.Helper()
31		for _, u := range st.MonthlyUsage {
32			if u.Period == p {
33				return u.Total
34			}
35		}
36		t.Fatalf("usage for %s not found in %+v", p, st.MonthlyUsage)
37		return 0
38	}
39	
40	// statusBillSummary 在状态结果中查找指定账期的账单摘要，缺失即终止。
41	func statusBillSummary(t *testing.T, st AccountStatus, p Month) BillSummary {
42		t.Helper()
43		for _, b := range st.Bills {
44			if b.Period == p {
45				return b
46			}
47		}
48		t.Fatalf("bill for %s not found in %+v", p, st.Bills)
49		return BillSummary{}
50	}
