97	// assertRealFixtureStatus 断言状态显示夹具中的真实记录：用量按账期先后
98	// 为一月 12、二月 30；一月账单已付清，二月账单未付；订阅有效且等待原定终止。
99	func assertRealFixtureStatus(t *testing.T, st AccountStatus, end time.Time) {
100		t.Helper()
101		if !st.Subscribed {
102			t.Fatalf("Subscribed = false, status = %+v", st)
103		}
104		if st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(end) {
105			got := "<nil>"
106			if st.ScheduledEnd != nil {
107				got = st.ScheduledEnd.String()
108			}
109			t.Fatalf("ScheduledEnd = %s, want %v", got, end)
110		}
111		if len(st.MonthlyUsage) != 2 ||
112			st.MonthlyUsage[0].Period != jan(2026) || st.MonthlyUsage[0].Total != 12 ||
113			st.MonthlyUsage[1].Period != feb(2026) || st.MonthlyUsage[1].Total != 30 {
114			t.Fatalf("monthly usage = %+v, want jan=12 feb=30 in period order", st.MonthlyUsage)
115		}
116		if len(st.Bills) != 2 {
117			t.Fatalf("bills = %+v, want two summaries", st.Bills)
118		}
119		jb := st.Bills[0]
120		if jb.Period != jan(2026) || jb.TotalDue != 1200 || jb.Paid != 1200 || jb.Balance != 0 || !jb.Settled {
121			t.Fatalf("jan summary = %+v, want paid 1200 settled", jb)
122		}
123		fb := st.Bills[1]
124		if fb.Period != feb(2026) || fb.TotalDue != 3000 || fb.Paid != 0 || fb.Balance != 3000 || fb.Settled {
125			t.Fatalf("feb summary = %+v, want unpaid 3000 not settled", fb)
126		}
127	}
128	
129	// TestStatusUsageBillsAndEndMutationsDoNotReachAccount 验证调用方篡改返回的
130	// 用量总数、账单摘要（已付金额、余额、付清状态）以及终止时刻（改成更早或
131	// 更晚、整体替换指针）都只留在该份结果中：再次查询仍看到真实数据，
132	// MonthlyUsage 与 GetBill 的计量、收款结果也不受摘要改动影响；重排或替换
133	// 返回的列表同样不能影响下一次查询按账期先后展示的记录。
134	func TestStatusUsageBillsAndEndMutationsDoNotReachAccount(t *testing.T) {
135		s, _, end := setupIndependenceFixture(t)
136	
137		st, err := s.Status("u")
138		if err != nil {
139			t.Fatal(err)
140		}
141		assertRealFixtureStatus(t, st, end)
142	
143		// 篡改这份结果里的用量总数与账单摘要。
144		st.MonthlyUsage[0].Total = 999012
145		st.MonthlyUsage[1].Total = 999030
146		st.Bills[0].Paid = 1
147		st.Bills[0].Balance = 1199
148		st.Bills[0].Settled = false
149		st.Bills[1].Paid = 3000
150		st.Bills[1].Balance = 0
151		st.Bills[1].Settled = true
152		// 终止时刻先原地改成更早，再整体替换成更晚的指针。
153		*st.ScheduledEnd = utc(2026, 3, 10, 0, 0)
154		later := utc(2026, 12, 1, 0, 0)
155		st.ScheduledEnd = &later
156	
157		// 再次查询：真实记录与原定终止时刻原样呈现。
158		st, err = s.Status("u")
159		if err != nil {
160			t.Fatal(err)
161		}
162		assertRealFixtureStatus(t, st, end)
163	
164		// 按月查询用量与查询账单同样保持原值，不被摘要篡改波及。
165		if u, err := s.MonthlyUsage("u", jan(2026)); err != nil || u.Total != 12 {
166			t.Fatalf("jan MonthlyUsage = %+v %v, want total 12", u, err)
167		}
168		if u, err := s.MonthlyUsage("u", feb(2026)); err != nil || u.Total != 30 {
169			t.Fatalf("feb MonthlyUsage = %+v %v, want total 30", u, err)
170		}
171		jb, err := s.GetBill("u", jan(2026))
172		if err != nil || jb.Paid != 1200 || jb.Balance != 0 || !jb.Settled {
173			t.Fatalf("jan GetBill = %+v %v, want paid 1200 settled", jb, err)
174		}
175		fb, err := s.GetBill("u", feb(2026))
176		if err != nil || fb.Paid != 0 || fb.Balance != 3000 || fb.Settled {
177			t.Fatalf("feb GetBill = %+v %v, want unpaid 3000", fb, err)
178		}
179	
180		// 重排返回列表、替换其中元素乃至整张列表，下一次查询仍按账期先后展示。
181		st.MonthlyUsage[0], st.MonthlyUsage[1] = st.MonthlyUsage[1], st.MonthlyUsage[0]
182		st.MonthlyUsage[0] = Usage{Period: Month{Year: 2099, Month: time.December}, Total: 7}
183		st.Bills = []BillSummary{{Period: Month{Year: 2099, Month: time.December}, TotalDue: 1, Paid: 1, Settled: true}}
184	
185		st, err = s.Status("u")
186		if err != nil {
187			t.Fatal(err)
188		}
189		assertRealFixtureStatus(t, st, end)
190	}
191	
192	// TestTwoStatusSnapshotsAreIndependent 验证同一账户分别取得的两份状态彼此
193	// 独立：重排、扩缩、替换第一份的用量/账单列表并改写其终止时刻，不改写第二份；
194	// 之后再改第二份，新查询与第一份各自保留自己的内容。
195	func TestTwoStatusSnapshotsAreIndependent(t *testing.T) {
196		s, _, end := setupIndependenceFixture(t)
197	
198		a, err := s.Status("u")
199		if err != nil {
200			t.Fatal(err)
201		}
202		b, err := s.Status("u")
203		if err != nil {
204			t.Fatal(err)
205		}
206		assertRealFixtureStatus(t, a, end)
207		assertRealFixtureStatus(t, b, end)
208	
209		// 全面篡改 a：原地改值、替换元素、倒序、追加虚假账期、改终止时刻。
210		a.MonthlyUsage[0].Total = 11111
211		a.MonthlyUsage[1] = Usage{Period: Month{Year: 2099, Month: time.December}, Total: 22222}
212		a.MonthlyUsage[0], a.MonthlyUsage[1] = a.MonthlyUsage[1], a.MonthlyUsage[0]
213		a.MonthlyUsage = append(a.MonthlyUsage, Usage{Period: Month{Year: 1999, Month: time.January}, Total: 33333})
214		a.Bills[0].Paid, a.Bills[0].Balance, a.Bills[0].Settled = 500, 700, false
215		a.Bills[1] = BillSummary{Period: Month{Year: 2099, Month: time.December}, TotalDue: 1}
216		*a.ScheduledEnd = utc(2020, 1, 1, 0, 0)
217	
218		// b 与新查询都仍是真实数据。
219		assertRealFixtureStatus(t, b, end)
220		c, err := s.Status("u")
221		if err != nil {
222			t.Fatal(err)
223		}
224		assertRealFixtureStatus(t, c, end)
225	
226		// 反向再改 b：c 与账户真实数据不变，a 保留自己被篡改掉的内容。
227		b.MonthlyUsage[0].Total = 44444
228		b.Bills = nil
229		later := utc(2027, 1, 1, 0, 0)
230		b.ScheduledEnd = &later
231		c, err = s.Status("u")
232		if err != nil {
233			t.Fatal(err)
234		}
235		assertRealFixtureStatus(t, c, end)
236		if len(a.MonthlyUsage) != 3 || a.MonthlyUsage[0].Total != 22222 ||
237			a.MonthlyUsage[1].Total != 11111 || a.MonthlyUsage[2].Total != 33333 {
238			t.Fatalf("snapshot a changed after editing b: %+v", a.MonthlyUsage)
239		}
240		if !a.ScheduledEnd.Equal(utc(2020, 1, 1, 0, 0)) {
241			t.Fatalf("snapshot a end changed after editing b: %v", *a.ScheduledEnd)
242		}
243	}
244	
245	// TestStatusSnapshotFreezesAcrossUsagePaymentAndUndoCancel 验证反方向的独立：
246	// 保存一份未改动的状态后，通过正常功能为尚未出账的三月补报用量、为二月账单
247	// 登记部分付款、再撤回取消——新查询显示更新后的累计用量、已付金额、余额与
248	// 空终止时刻；旧结果保留取得时的数值、付清状态与当时的终止安排。篡改旧结果
249	// 不能重新登记取消，也不能让已撤回的订阅在原定时刻终止。
250	func TestStatusSnapshotFreezesAcrossUsagePaymentAndUndoCancel(t *testing.T) {
251		s, clk, end := setupIndependenceFixture(t)
252	
253		saved, err := s.Status("u")
254		if err != nil {
255			t.Fatal(err)
256		}
257		assertRealFixtureStatus(t, saved, end)
258	
259		// 正常操作一：为尚未出账的三月（当前订阅覆盖）补报 8 单位。
260		mustRecordEvent(t, s, Event{AccountID: "u", EventID: "e-mar", At: utc(2026, 3, 4, 0, 0), Quantity: 8})
261		// 正常操作二：为二月账单登记部分付款 400，余额变 2600，仍未付清。
262		pr, err := s.RecordPayment("u", "pay-feb-1", feb(2026), 400)
263		if err != nil || pr.BillBalance != 2600 || pr.Settled {
264			t.Fatalf("partial payment = %+v %v, want balance 2600 not settled", pr, err)
265		}
266	
267		fresh, err := s.Status("u")
268		if err != nil {
269			t.Fatal(err)
270		}
271		if len(fresh.MonthlyUsage) != 3 ||
272			fresh.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 12}) ||
273			fresh.MonthlyUsage[1] != (Usage{Period: feb(2026), Total: 30}) ||
274			fresh.MonthlyUsage[2] != (Usage{Period: mar(2026), Total: 8}) {
275			t.Fatalf("fresh usage = %+v, want jan=12 feb=30 mar=8", fresh.MonthlyUsage)
276		}
277		fb := statusBillSummary(t, fresh, feb(2026))
278		if fb.Paid != 400 || fb.Balance != 2600 || fb.Settled {
279			t.Fatalf("fresh feb summary = %+v, want paid 400 balance 2600", fb)
280		}
281	
282		// 旧结果保留取得时的数值与付清状态：没有三月用量，二月未付，一月仍付清。
283		if len(saved.MonthlyUsage) != 2 ||
284			statusUsageTotal(t, saved, jan(2026)) != 12 ||
285			statusUsageTotal(t, saved, feb(2026)) != 30 {
286			t.Fatalf("saved usage changed = %+v", saved.MonthlyUsage)
287		}
288		savedFeb := statusBillSummary(t, saved, feb(2026))
289		if savedFeb.Paid != 0 || savedFeb.Balance != 3000 || savedFeb.Settled {
290			t.Fatalf("saved feb summary changed = %+v", savedFeb)
291		}
292	
293		// 正常操作三：撤回取消。新查询不再显示终止时刻，订阅继续有效。
294		clk.t = utc(2026, 3, 6, 12, 0)
295		if err := s.UndoCancelSubscription("u"); err != nil {
296			t.Fatalf("undo cancel: %v", err)
297		}
298		fresh, err = s.Status("u")
299		if err != nil {
300			t.Fatal(err)
301		}
302		if !fresh.Subscribed || fresh.ScheduledEnd != nil {
303			t.Fatalf("status after undo = %+v, want subscribed with nil end", fresh)
304		}
305		// 旧结果保留当时的安排。
306		if saved.ScheduledEnd == nil || !saved.ScheduledEnd.Equal(end) {
307			t.Fatalf("saved end changed after undo = %+v, want %v", saved.ScheduledEnd, end)
308		}
309	
310		// 篡改旧结果：既不能重新登记取消，也不能改变撤回状态。
311		*saved.ScheduledEnd = utc(2026, 3, 10, 0, 0)
312		fakeLater := utc(2026, 12, 1, 0, 0)
313		saved.ScheduledEnd = &fakeLater
314		fresh, err = s.Status("u")
315		if err != nil {
316			t.Fatal(err)
317		}
318		if !fresh.Subscribed || fresh.ScheduledEnd != nil {
319			t.Fatalf("tampering saved end registered a cancellation: %+v", fresh)
320		}
321	
322		// 越过原定终止时刻：已撤回的订阅不在 4/1 终止，仍无终止安排。
323		clk.t = utc(2026, 4, 2, 0, 0)
324		fresh, err = s.Status("u")
325		if err != nil {
326			t.Fatal(err)
327		}
328		if !fresh.Subscribed {
329			t.Fatalf("subscription ended at original time despite undo: %+v", fresh)
330		}
331		if fresh.ScheduledEnd != nil {
332			t.Fatalf("unexpected scheduled end after undo: %v", *fresh.ScheduledEnd)
333		}
334		if fresh.CurrentTerms.PlanID != "a" {
335			t.Fatalf("current terms after undo = %+v, want plan a", fresh.CurrentTerms)
336		}
337		// 旧结果继续表示取得时尚在等待取消。
338		if !saved.Subscribed || saved.ScheduledEnd == nil || !saved.ScheduledEnd.Equal(fakeLater) {
339			t.Fatalf("saved result mutated by later operations: %+v", saved)
340		}
341	}
342	
343	// TestCancellationEndsAtRegisteredTimeDespiteSnapshotTampering 验证未撤回的
344	// 取消严格按最初登记的终止时刻结束订阅：把旧结果中的终止时刻改早，订阅不会
345	// 提前结束；改晚，到达原定时刻仅查询状态也立即显示无有效订阅、无当前套餐、
346	// 无终止安排，历史用量与账单继续可查；旧结果定格在取得时的等待取消状态。
347	func TestCancellationEndsAtRegisteredTimeDespiteSnapshotTampering(t *testing.T) {
348		s, clk, end := setupIndependenceFixture(t)
349	
350		saved, err := s.Status("u")
351		if err != nil {
352			t.Fatal(err)
353		}
354		assertRealFixtureStatus(t, saved, end)
355	
356		// 把旧结果的终止时刻改到更早的 3/10：真实订阅不得提前终止。
357		early := utc(2026, 3, 10, 0, 0)
358		*saved.ScheduledEnd = early
359		clk.t = utc(2026, 3, 12, 0, 0)
360		st, err := s.Status("u")
361		if err != nil {
362			t.Fatal(err)
363		}
364		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(end) {
365			t.Fatalf("subscription ended at tampered early time: %+v", st)
366		}
367		if st.CurrentTerms.PlanID != "a" {
368			t.Fatalf("current terms = %+v, want plan a while waiting", st.CurrentTerms)
369		}
370	
371		// 再把旧结果的终止时刻改到更晚：原定时刻之前订阅仍然有效。
372		fakeLate := utc(2026, 12, 1, 0, 0)
373		saved.ScheduledEnd = &fakeLate
374		clk.t = utc(2026, 3, 31, 23, 59)
375		st, _ = s.Status("u")
376		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(end) {
377			t.Fatalf("status just before registered end = %+v", st)
378		}
379	
380		// 到达原定终止时刻，即使只查询状态：无有效订阅、无当前套餐、无终止安排。
381		clk.t = end
382		st, _ = s.Status("u")
383		if st.Subscribed {
384			t.Fatalf("Subscribed = true at registered end, status = %+v", st)
385		}
386		if st.CurrentTerms != (PlanTerms{}) {
387			t.Fatalf("CurrentTerms = %+v at registered end, want zero value", st.CurrentTerms)
388		}
389		if st.ScheduledEnd != nil {
390			t.Fatalf("ScheduledEnd = %v after end, want nil", *st.ScheduledEnd)
391		}
392		// 历史用量与账单继续可查，次序不变。
393		if len(st.MonthlyUsage) != 2 ||
394			st.MonthlyUsage[0].Period != jan(2026) || st.MonthlyUsage[0].Total != 12 ||
395			st.MonthlyUsage[1].Period != feb(2026) || st.MonthlyUsage[1].Total != 30 {
396			t.Fatalf("history usage after end = %+v", st.MonthlyUsage)
397		}
398		if len(st.Bills) != 2 || st.Bills[0].Period != jan(2026) || st.Bills[1].Period != feb(2026) {
399			t.Fatalf("history bills after end = %+v", st.Bills)
400		}
401	
402		// 旧结果继续表示取得时尚在等待取消，不被后来的查询改写。
403		if !saved.Subscribed || saved.ScheduledEnd == nil || !saved.ScheduledEnd.Equal(fakeLate) {
404			t.Fatalf("saved waiting status changed = %+v", saved)
405		}
406	}
407	
408	// TestStatusWithoutCancellationKeepsEndNil 验证没有取消安排时 ScheduledEnd
409	// 为空，调用方在返回结果中凭空填入终止时刻不能制造取消安排：后续查询与跨月
410	// 后的查询都仍显示订阅有效、终止时刻为空。
411	func TestStatusWithoutCancellationKeepsEndNil(t *testing.T) {
412		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
413		mustPlan(t, s, planDef("a", 1000, 10, 100, 0))
414		mustAccount(t, s, "u")
415		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
416		mustRecordEvent(t, s, Event{AccountID: "u", EventID: "e-jan", At: utc(2026, 1, 20, 0, 0), Quantity: 12})
417		clk.t = utc(2026, 2, 20, 12, 0)
418		mustRecordEvent(t, s, Event{AccountID: "u", EventID: "e-feb", At: utc(2026, 2, 20, 0, 0), Quantity: 30})
419		clk.t = utc(2026, 3, 1, 0, 0)
420		mustBill(t, s, "u", jan(2026))
421		mustBill(t, s, "u", feb(2026))
422	
423		st, err := s.Status("u")
424		if err != nil {
425			t.Fatal(err)
426		}
427		if !st.Subscribed || st.ScheduledEnd != nil {
428			t.Fatalf("status without cancellation = %+v, want subscribed nil end", st)
429		}
430	
431		// 在返回结果中凭空填入终止时刻并篡改列表。
432		fabricated := utc(2026, 4, 1, 0, 0)
433		st.ScheduledEnd = &fabricated
434		st.MonthlyUsage[0].Total = 1
435	
436		st, err = s.Status("u")
437		if err != nil {
438			t.Fatal(err)
439		}
440		if !st.Subscribed || st.ScheduledEnd != nil {
441			t.Fatalf("editing result fabricated a cancellation: %+v", st)
442		}
443		if statusUsageTotal(t, st, jan(2026)) != 12 {
444			t.Fatalf("usage changed after editing result: %+v", st.MonthlyUsage)
445		}
446	
447		// 跨月后仍无终止安排，订阅持续有效。
448		clk.t = utc(2026, 5, 1, 0, 0)
449		st, err = s.Status("u")
450		if err != nil {
451			t.Fatal(err)
452		}
453		if !st.Subscribed || st.ScheduledEnd != nil {
454			t.Fatalf("fabricated end terminated the subscription: %+v", st)
455		}
456	}
